CREATE TABLE chat_rooms (
 id CHAR(36) PRIMARY KEY,kind VARCHAR(12) NOT NULL,title VARCHAR(100) NOT NULL DEFAULT '',owner_id CHAR(36) NOT NULL,direct_key VARCHAR(73) NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(owner_id) REFERENCES profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE chat_members (
 room_id CHAR(36) NOT NULL,student_id CHAR(36) NOT NULL,last_read_at DATETIME(3) NULL,joined_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(room_id,student_id),
 FOREIGN KEY(room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE chat_messages (
 id CHAR(36) PRIMARY KEY,room_id CHAR(36) NOT NULL,sender_id CHAR(36) NOT NULL,client_id CHAR(36) NOT NULL,body VARCHAR(2000) NOT NULL,hidden SMALLINT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(sender_id,client_id),INDEX idx_chat_messages_room(room_id,created_at,id),
 FOREIGN KEY(room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE,FOREIGN KEY(sender_id) REFERENCES profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE chat_blocks (
 student_id CHAR(36) NOT NULL,peer_id CHAR(36) NOT NULL,PRIMARY KEY(student_id,peer_id),FOREIGN KEY(student_id) REFERENCES profiles(id) ON DELETE CASCADE,FOREIGN KEY(peer_id) REFERENCES profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE chat_reports (
 id CHAR(36) PRIMARY KEY,message_id CHAR(36) NOT NULL,reporter_id CHAR(36) NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'open',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(message_id,reporter_id),
 FOREIGN KEY(message_id) REFERENCES chat_messages(id) ON DELETE CASCADE,FOREIGN KEY(reporter_id) REFERENCES profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
